style.css:
@-moz-document domain("youtube.com") {
/* 1. HIDE RED DOT */
    .ytp-scrubber-button {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    /* 2. FAWN ANIMATION (FLIPPED) */
    .ytp-scrubber-button:after {
        content: "";
        display: block;
        width: 70px;
        height: 70px;
        
        background: url("https://media.tenor.com/bcQrnFFc6CYAAAAi/fawn-run-transparent.gif") no-repeat center;
        background-size: contain;
        
        position: absolute;
        top: -38px;   
        left: -25px;   
        
        /* THE FIX: FLIP HORIZONTALLY TO RUN RIGHT */
        transform: scaleX(-1); 
        
        transition: transform 0.2s ease, filter 0.2s ease;
    }

    /* 3. MAGIC FOREST BAR */
    .ytp-play-progress {
        background: linear-gradient(90deg, #2e7d32, #76ff03) !important; 
        box-shadow: 0 0 15px #76ff03, 0 0 5px #b2ff59 !important; 
    }

    /* 4. HOVER EFFECT (KEEPS THE FLIP) */
    .ytp-scrubber-button:hover:after {
        /* We must include scaleX(-1) here too, or it will flip back when you touch it! */
        transform: scaleX(-1) scale(1.15) translateY(-5px); 
        
        filter: drop-shadow(0 0 8px #76ff03); 
    }
}
